using Microsoft.Win32;using System.Management;using System.Net.NetworkInformation;
namespace AssetFlow.Agent;
public sealed class InventoryCollector{public Task<Inventory> CollectAsync(){return Task.Run(()=>{var cs=Wmi("Win32_ComputerSystem","Manufacturer","Model","TotalPhysicalMemory");var bios=Wmi("Win32_BIOS","SerialNumber","SMBIOSBIOSVersion");var os=Wmi("Win32_OperatingSystem","Caption","Version");var cpu=Wmi("Win32_Processor","Name");var nic=NetworkInterface.GetAllNetworkInterfaces().FirstOrDefault(n=>n.OperationalStatus==OperationalStatus.Up&&n.NetworkInterfaceType!=NetworkInterfaceType.Loopback);var ip=nic?.GetIPProperties().UnicastAddresses.FirstOrDefault(x=>x.Address.AddressFamily==System.Net.Sockets.AddressFamily.InterNetwork)?.Address.ToString();var disks=DriveInfo.GetDrives().Where(d=>d.IsReady&&d.DriveType==DriveType.Fixed).Select(d=>new DiskInfo(d.Name,d.DriveFormat,d.TotalSize,d.AvailableFreeSpace)).ToList();return new Inventory(Environment.MachineName,S(bios,"SerialNumber"),S(cs,"Manufacturer"),S(cs,"Model"),Environment.UserName,null,S(os,"Caption")??Environment.OSVersion.VersionString,S(os,"Version")??"",S(cpu,"Name"),L(cs,"TotalPhysicalMemory"),S(bios,"SMBIOSBIOSVersion"),ip,nic?.GetPhysicalAddress().ToString(),BitLocker(),Firewall(),Defender(),disks,Software());});}
private static ManagementBaseObject? Wmi(string name,params string[] fields){using var s=new ManagementObjectSearcher($"SELECT {string.Join(',',fields)} FROM {name}");return s.Get().Cast<ManagementBaseObject>().FirstOrDefault();}private static string? S(ManagementBaseObject? o,string k)=>o?[k]?.ToString()?.Trim();private static long L(ManagementBaseObject? o,string k)=>long.TryParse(S(o,k),out var v)?v:0;
private static List<SoftwareInfo> Software(){var list=new List<SoftwareInfo>();foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32}){using var root=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,view).OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall");if(root==null)continue;foreach(var n in root.GetSubKeyNames()){using var k=root.OpenSubKey(n);var name=k?.GetValue("DisplayName")?.ToString();if(!string.IsNullOrWhiteSpace(name))list.Add(new(name,k?.GetValue("DisplayVersion")?.ToString(),k?.GetValue("Publisher")?.ToString()));}}return list.GroupBy(x=>$"{x.Name}|{x.Version}").Select(x=>x.First()).OrderBy(x=>x.Name).ToList();}
private static bool? BitLocker(){try{using var s=new ManagementObjectSearcher(@"root\CIMV2\Security\MicrosoftVolumeEncryption","SELECT ProtectionStatus FROM Win32_EncryptableVolume WHERE DriveLetter='C:'");return Convert.ToUInt32(s.Get().Cast<ManagementBaseObject>().FirstOrDefault()?["ProtectionStatus"]??0)==1;}catch{return null;}}private static bool? Firewall(){try{using var k=Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\StandardProfile");return Convert.ToInt32(k?.GetValue("EnableFirewall")??0)==1;}catch{return null;}}private static string Defender(){try{using var k=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows Defender\Real-Time Protection");return Convert.ToInt32(k?.GetValue("DisableRealtimeMonitoring")??0)==0?"Healthy":"Disabled";}catch{return"Unknown";}}}
